import { db } from "@/lib/db";

/**
 * The ONE money helper for the marketing comparison surface. Every Nxeon price
 * shown on a /compare or competitor-alternative page is derived from a live
 * `db.plan` record through here — there is not a single hard-coded Nxeon plan
 * price on those pages, so a catalogue edit propagates automatically and the
 * comparison can never advertise a number checkout won't honour.
 */
export function money(cents: number): string {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}

export type VpsPriceBand = {
  /** Cheapest active VPS plan. */
  fromCents: number;
  fromName: string;
  /** Dearest active VPS plan. */
  toCents: number;
  toName: string;
  /** "$6.49/mo" — the entry price, formatted. */
  fromLabel: string;
  /** "$32.99/mo" — the top price, formatted. */
  toLabel: string;
  /** "$6.49–$32.99/mo" — the full band, formatted for a single cell. */
  rangeLabel: string;
};

/**
 * Reads the live Cloud VPS catalogue and returns the active price band, or
 * `null` when no plans are active (callers fall back to neutral, price-free
 * copy so a page never invents a figure). Pages that call this MUST set
 * `export const dynamic = "force-dynamic"` so the band tracks the DB.
 */
export async function getVpsPriceBand(): Promise<VpsPriceBand | null> {
  const plans = await db.plan.findMany({
    where: { active: true },
    orderBy: { priceCents: "asc" },
    select: { name: true, priceCents: true },
  });
  if (plans.length === 0) return null;

  const from = plans[0];
  const to = plans[plans.length - 1];
  const fromLabel = `${money(from.priceCents)}/mo`;
  const toLabel = `${money(to.priceCents)}/mo`;
  const rangeLabel =
    from.priceCents === to.priceCents
      ? fromLabel
      : `${money(from.priceCents)}–${money(to.priceCents)}/mo`;

  return {
    fromCents: from.priceCents,
    fromName: from.name,
    toCents: to.priceCents,
    toName: to.name,
    fromLabel,
    toLabel,
    rangeLabel,
  };
}

import Link from "next/link";
import { Reveal } from "./Reveal";
import { IconCheck } from "./icons";

/**
 * Shared, DB-fed comparison table for the /compare surface and every
 * competitor-alternative page. One component so all eight comparisons read as
 * one designed thing, with the Nxeon column visually emphasised and an honest
 * "reflects our understanding" disclaimer baked in.
 *
 * It renders NO hard-coded Nxeon price: any Nxeon figure arrives already
 * derived from the live catalogue (see `lib/vps-price-band.ts`) via the caller,
 * either inside a row's `nxeon` string or the optional `fromLabel` header badge.
 */
export type CompareRow = { feature: string; nxeon: string; other: string };

export function CompareTable({
  competitor,
  rows,
  fromLabel,
  note,
}: {
  /** Competitor display name, e.g. "DigitalOcean". */
  competitor: string;
  rows: CompareRow[];
  /** DB-fed entry price, e.g. "$6.49/mo" — shown as a header badge when given. */
  fromLabel?: string;
  /** Optional trademark / accuracy disclaimer. A sensible default is used. */
  note?: string;
}) {
  const disclaimer =
    note ??
    `${competitor} is a trademark of its respective owner. Comparison reflects Nxeon's understanding at time of writing — always check each provider's current plans.`;

  return (
    <Reveal>
      <div className="card overflow-x-auto p-0">
        <table className="w-full min-w-[600px] text-sm">
          <thead>
            <tr className="border-b border-white/[0.08]">
              <th className="px-5 py-4 text-left text-[11px] font-semibold uppercase tracking-wider text-slate-500">
                Feature
              </th>
              <th className="bg-gradient-to-b from-brand-500/[0.10] to-transparent px-5 py-4 text-left align-top">
                <span className="grad-text text-sm font-bold">Nxeon</span>
                {fromLabel && (
                  <span className="mt-1 block text-[11px] font-medium normal-case tracking-normal text-brand-300">
                    from {fromLabel}
                  </span>
                )}
              </th>
              <th className="px-5 py-4 text-left text-[11px] font-semibold uppercase tracking-wider text-slate-500">
                {competitor}
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.feature} className="border-t border-white/[0.05] odd:bg-white/[0.015]">
                <td className="px-5 py-4 font-medium text-white">{r.feature}</td>
                <td className="bg-brand-500/[0.04] px-5 py-4 text-slate-200">
                  <span className="flex items-start gap-2">
                    <span className="mt-0.5 flex-none text-emerald-400">
                      <IconCheck size={15} />
                    </span>
                    <span>{r.nxeon}</span>
                  </span>
                </td>
                <td className="px-5 py-4 text-slate-400">{r.other}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="mt-4 text-center text-xs text-slate-500">{disclaimer}</p>
    </Reveal>
  );
}

/**
 * The paired "Choose Nxeon if… / Choose {competitor} if…" decision block used
 * beneath every comparison table. Kept here so all eight pages stay consistent.
 */
export function ChooseGrid({
  competitor,
  nxeon,
  other,
}: {
  competitor: string;
  nxeon: string[];
  other: string[];
}) {
  return (
    <div className="mx-auto mt-10 grid max-w-3xl gap-4 sm:grid-cols-2">
      <Reveal className="card border-brand-500/25 ring-1 ring-brand-500/15">
        <h3 className="text-base font-semibold text-white">
          Choose <span className="grad-text">Nxeon</span> if…
        </h3>
        <ul className="mt-3 space-y-2 text-sm text-slate-300">
          {nxeon.map((p) => (
            <li key={p} className="flex items-start gap-2">
              <span className="mt-0.5 flex-none text-emerald-400">
                <IconCheck size={15} />
              </span>
              {p}
            </li>
          ))}
        </ul>
        <Link href="/register" className="btn-primary mt-5 inline-flex px-4 py-2 text-sm">
          Create your account
        </Link>
      </Reveal>
      <Reveal delay={80} className="card">
        <h3 className="text-base font-semibold text-white">Choose {competitor} if…</h3>
        <ul className="mt-3 space-y-2 text-sm text-slate-400">
          {other.map((p) => (
            <li key={p} className="flex items-start gap-2">
              <span className="mt-0.5 flex-none text-slate-600">•</span>
              {p}
            </li>
          ))}
        </ul>
      </Reveal>
    </div>
  );
}

import Link from "next/link";
import { Section, SectionTitle, PageHero } from "./primitives";
import { CtaBand } from "./sections";
import { FaqJsonLd } from "./StructuredData";
import { CompareTable, ChooseGrid, type CompareRow } from "./CompareTable";

/**
 * One shared layout for every competitor-alternative / "Nxeon vs X" page, so all
 * eight comparisons render as a single designed, honest thing: hero → emphasised
 * DB-fed comparison table → "which should you pick" decision grid → FAQ → CTA.
 *
 * Each page is now a thin, mostly-static data file that reads the live VPS price
 * band from the catalogue and passes it in — there is no hard-coded Nxeon price
 * anywhere on this surface, and the layout/markup lives in exactly one place.
 */
export function ComparePageLayout({
  competitor,
  heroTitle,
  heroSub,
  fromLabel,
  rows,
  chooseNxeon,
  chooseOther,
  faq,
  note,
}: {
  competitor: string;
  /** Everything before the gradient "alternative"/competitor highlight. */
  heroTitle: string;
  heroSub: string;
  /** DB-fed entry price, e.g. "$6.49/mo". Omitted safely when no plans exist. */
  fromLabel?: string;
  rows: CompareRow[];
  chooseNxeon: string[];
  chooseOther: string[];
  faq: { q: string; a: string }[];
  note?: string;
}) {
  return (
    <>
      <FaqJsonLd items={faq} />

      <PageHero
        eyebrow="Comparison"
        title={heroTitle}
        highlight={competitor}
        sub={heroSub}
        primary={{ label: "Create your account", href: "/register" }}
        secondary={{ label: "See all comparisons", href: "/compare" }}
      />

      <Section tone="base" size="md">
        <CompareTable competitor={competitor} rows={rows} fromLabel={fromLabel} note={note} />
      </Section>

      <Section tone="panel" size="md">
        <SectionTitle eyebrow="Which should you pick?" title="A straight answer" />
        <ChooseGrid competitor={competitor} nxeon={chooseNxeon} other={chooseOther} />
      </Section>

      <Section tone="base" size="md">
        <SectionTitle eyebrow="FAQ" title="Common questions" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {faq.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                </span>
              </summary>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </details>
          ))}
        </div>
        <div className="mt-8 text-center text-sm text-slate-500">
          Comparing against something else?{" "}
          <Link href="/compare" className="text-brand-300 hover:text-brand-200">
            See all comparisons
          </Link>
          .
        </div>
      </Section>

      <Section tone="deep" size="lg">
        <CtaBand />
      </Section>
    </>
  );
}

