import type { Metadata } from "next";
import { ComparePageLayout } from "@/components/marketing/ComparePageLayout";
import type { CompareRow } from "@/components/marketing/CompareTable";
import { getVpsPriceBand } from "@/lib/vps-price-band";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const metadata: Metadata = {
  title: "Nxeon vs DigitalOcean — an honest VPS comparison",
  description:
    "How Nxeon compares to DigitalOcean for cloud VPS hosting: pricing, NVMe storage, game servers, dedicated IPs and where each one is the better fit.",
  alternates: { canonical: "/vps-vs-digitalocean" },
  openGraph: {
    type: "article",
    title: "Nxeon vs DigitalOcean — an honest VPS comparison",
    description:
      "Pricing, NVMe storage, game servers and dedicated IPs compared. An honest look at where each provider wins.",
    url: `${APP_URL}/vps-vs-digitalocean`,
  },
};

// Prices track the live catalogue — see lib/vps-price-band.ts. Set force-dynamic
// so the DB-fed band is read on every request.
export const dynamic = "force-dynamic";

const ROWS: CompareRow[] = [
  { feature: "Best for", nxeon: "Indie devs, game servers, side projects near Asia", other: "Teams wanting a global managed-cloud ecosystem" },
  { feature: "Storage", nxeon: "Enterprise NVMe SSD (ZFS mirror)", other: "SSD / NVMe depending on Droplet type" },
  { feature: "Locations", nxeon: "Single Singapore node", other: "Many regions across the globe" },
  { feature: "Game servers", nxeon: "First-class — Minecraft & more, one-click", other: "Possible, but you build it yourself" },
  { feature: "Dedicated IPv4", nxeon: "Included, no extra fee", other: "Included per Droplet" },
  { feature: "Domains", nxeon: "Register & manage domains in the same dashboard", other: "Not a domain registrar" },
  { feature: "Root access", nxeon: "Full root over SSH", other: "Full root over SSH" },
  { feature: "Managed services", nxeon: "Focused, unmanaged VPS", other: "Large managed ecosystem (DBs, k8s, LB…)" },
];

const CHOOSE_NXEON = [
  "Your players or users are in Asia-Pacific",
  "You want a game server up in minutes",
  "You'd like domains and hosting in one dashboard",
  "You want a simple, low-cost box you fully control",
];
const CHOOSE_OTHER = [
  "You need multiple global regions",
  "You want managed databases, k8s or load balancers",
  "You're building a distributed production platform",
  "You value a large third-party integration ecosystem",
];

const FAQ = [
  {
    q: "Is Nxeon cheaper than DigitalOcean?",
    a: "Nxeon focuses on a lean, single-node VPS offering, which lets us keep entry pricing low for hobby and side-project workloads. DigitalOcean offers more regions and managed products, which can be worth the premium for distributed production teams. Compare the specific plan you need rather than the headline price.",
  },
  {
    q: "Where are Nxeon servers located?",
    a: "Nxeon runs a single node in Singapore. If your users are in Asia-Pacific, that means low latency without paying for a global footprint you don't use. If you specifically need US or EU regions, DigitalOcean's broader location list is the better fit.",
  },
  {
    q: "Can I run a Minecraft or game server on either?",
    a: "Yes on both, but Nxeon treats game servers as a first-class use case with one-click setup and sensible defaults, whereas on DigitalOcean you configure everything yourself on a plain Droplet.",
  },
  {
    q: "Does Nxeon offer managed databases and load balancers like DigitalOcean?",
    a: "No. Nxeon is a focused, unmanaged VPS with full root access — you install and manage your own stack. DigitalOcean sells a broad menu of managed add-ons if you'd rather not run them yourself.",
  },
];

export default async function VpsVsDigitalOcean() {
  const band = await getVpsPriceBand();
  return (
    <ComparePageLayout
      competitor="DigitalOcean"
      heroTitle="Nxeon vs"
      heroHighlight="DigitalOcean"
      heroSub="Both give you a real Linux box with full root access. The honest difference comes down to focus: Nxeon is a lean NVMe VPS built for game servers and side projects near Asia, while DigitalOcean is a broad global managed cloud. Here's how they line up."
      fromLabel={band?.fromLabel}
      rows={ROWS}
      chooseNxeon={CHOOSE_NXEON}
      chooseOther={CHOOSE_OTHER}
      faq={FAQ}
    />
  );
}

import type { Metadata } from "next";
import { ComparePageLayout } from "@/components/marketing/ComparePageLayout";
