const vpsFrom = vpsPlans.length ? Math.min(...vpsPlans.map((p) => p.priceCents)) : null;

// Cheapest plan per product line, for the "at a glance" overview — every
// figure below is the same DB record the section deep-dives read, so the
// summary and the detail can never disagree.
const cheapest = <T extends { priceCents: number }>(arr: T[]): T | null =>
  arr.length ? arr.reduce((a, b) => (b.priceCents < a.priceCents ? b : a)) : null;
const planFrom = (p: { priceCents: number; termMonths?: number } | null): string =>
  p ? `${money(p.priceCents)}${p.termMonths && p.termMonths > 1 ? ` / ${p.termMonths} mo` : "/mo"}` : "—";
const vpsMin = cheapest(vpsPlans);
const gameMin = cheapest(gamePlans);
const hostingMin = cheapest(hostingPlans);
const emailMin = cheapest(emailPlans);
const domainMin = POPULAR_TLDS.length ? Math.min(...POPULAR_TLDS.map((t) => t.fromCents)) : null;

// One-row-per-product overview. `from` is always DB-derived (domains are the
// labelled "indicative" exception, matching the domains section below).
const OVERVIEW: { icon: React.ReactNode; name: string; from: string; billing: string; bestFor: string; href: string }[] = [
  { icon: <IconTerminal />, name: "Cloud VPS", from: planFrom(vpsMin), billing: "Monthly · resize anytime", bestFor: "Full root, any stack", href: "#vps" },
  { icon: <IconGame />, name: "Game Servers", from: gameMin ? `from ${planFrom(gameMin)}` : "—", billing: "Per game · monthly", bestFor: "Low-latency game hosting", href: "#game-servers" },
  {
    icon: <IconApps />,
    name: "Shared Hosting",
    from: planFrom(hostingMin),
    billing: hostingHasPromo ? "Monthly · first month free" : "Monthly · no lock-in",
    bestFor: "WordPress sites, no server",
    href: "#hosting",
  },
  { icon: <IconMail />, name: "Business Email", from: planFrom(emailMin), billing: "Monthly", bestFor: "Mailboxes at your domain", href: "#email" },
  { icon: <IconGlobe />, name: "Domains", from: domainMin != null ? `from ${money(domainMin)}/yr*` : "—", billing: "Yearly registration", bestFor: "Own the name + DNS", href: "#domains" },
];

